let aufnr, vbeln;

if (msg.payload && typeof msg.payload === 'object') {
    if (msg.payload.aufnr) {
        aufnr = msg.payload.aufnr;
    }
    if (msg.payload.vbeln) {
        vbeln = msg.payload.vbeln;
    }
} else if (typeof msg.payload === 'string') {
    try {
        const data = JSON.parse(msg.payload);
        if (data.aufnr) aufnr = data.aufnr;
        if (data.vbeln) vbeln = data.vbeln;
    } catch (e) {
        aufnr = msg.payload;
    }
}

if (!aufnr && !vbeln) {
    node.error("Weder Auftragsnummer (aufnr) noch Verkaufsbelegnummer (vbeln) gefunden");
    return null;
}

// Speichere die Nummern im msg-Objekt
if (aufnr) msg.aufnr = aufnr;
if (vbeln) msg.vbeln = vbeln;

// Erstelle die SQL-Abfrage je nach vorhandenem Wert
if (aufnr) {
    msg.request_value='aufnr';
    msg.query = `
SELECT    
    aufnr,
    posnr,
    psmng,
    kdauf as vbeln,
    afpo.matnr,
    CASE WHEN ltrmi != '0001-01-01 BC' THEN ltrmi END as ltmri,
    ltrmp,
    dwerk,
    afpo.auditinsertdate,
	maktx,
	substring(maktx FROM ' ([^ ]+)') AS dispo_group
FROM 
    ods.fa_afpo afpo
	join ods.st_makt makt on afpo.matnr = makt.matnr and makt.spras='D'
WHERE 
    aufnr = '${aufnr}'
LIMIT 1;
`;
} else if (vbeln) {
    msg.request_value='vbeln';
    msg.query = `

SELECT    
    aufnr,
    posnr,
    psmng,
    kdauf as vbeln,
    afpo.matnr,
    CASE WHEN ltrmi != '0001-01-01 BC' THEN ltrmi END as ltmri,
    ltrmp,
    dwerk,
    afpo.auditinsertdate,
	maktx,
	substring(maktx FROM ' ([^ ]+)') AS dispo_group
FROM 
    ods.fa_afpo afpo
	join ods.st_makt makt on afpo.matnr = makt.matnr and makt.spras='D'
WHERE 
    kdauf = '${vbeln}' and maktx like 'PAK%' 
`;
}

node.debug(`SQL-Abfrage für ${aufnr ? "Auftragsnummer " + aufnr : "Verkaufsbelegnummer " + vbeln} erstellt`);
return msg;

function cleanupRequestedOrders() {
    const requestedOrders = flow.get("requestedOrders_vbap") || [];
    if (requestedOrders.length === 0) return;

    const sixMonthsAgo = new Date();
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

    const filteredOrders = requestedOrders.filter(entry => {
        const entryDate = new Date(entry.timestamp);
        return entryDate > sixMonthsAgo;
    });

    flow.set("requestedOrders_vbap", filteredOrders);
    node.debug(`Bereinigung durchgeführt: ${requestedOrders.length - filteredOrders.length} alte Einträge entfernt`);
}
cleanupRequestedOrders()
return msg;

// Hole die Liste der angefragten Verkaufsbelegnummern
const requestedOrders = flow.get("requestedOrders_vbap") || [];

if (requestedOrders.length === 0) {
    node.warn("Keine Verkaufsbelegnummern zum Aktualisieren vorhanden");
    return null;
}

// Erstelle für jede Verkaufsbelegnummer eine Nachricht
const messages = [];

requestedOrders.forEach(entry => {
    messages.push({
        vbeln: entry.vbeln,
        query: `SELECT
    vbap.auditinsertdate,
    vbap.vbeln, vbap.posnr, vbap.matnr, vbap.zzmbdat, vbap.zzprwrk, vbap.zzhstoff, vbap.zzastoff, vbap.meins, vbap.spart,
    makt.maktx as hstoff,
	makt_a.maktx as astoff
FROM 
    ods.fa_vbap vbap LEFT JOIN ods.st_makt makt on makt.matnr=vbap.zzhstoff and makt.spras='D'
	LEFT JOIN ods.st_makt makt_a on makt_a.matnr=vbap.zzastoff and makt_a.spras='D'
WHERE  
            vbeln = '${entry.vbeln}';
        `
    });
});

node.debug(`${messages.length} Verkaufsbelegnummern werden aktualisiert`);
return [messages];

