// Initialize the latestStates object in global context if not already set
// SY = System State
// ST = System Tool
// FS = Feed State
// CF = Cradle Feeder State
// ER = Error Messages
flow.set("latestStates", {})
// Initialize the latestStates object in the node context
const monitoredCommands = ["SY", "ST", "FS", "CF", "ER", "JB"];
const machines = ["zund-cut01", "zund-cut02", "zund-cut03", "zund-cut04", "zund-cut05",
    "zund-cut06", "zund-cut07", "zund-cut08", "zund-cut09", "zund-cut10"];

let latestStates = flow.get("latestStates") || {};
let timestamp_ms = Date.now()

// Prepopulate the structure for all machines and monitored commands
machines.forEach(machine => {
    if (!latestStates[machine]) {
        latestStates[machine] = {};
        monitoredCommands.forEach(command => {
            latestStates[machine][command] = { timestamp: timestamp_ms, parameters: [] };
            latestStates[machine]["timestamp_ms"] = timestamp_ms;
        });
    }
});
flow.set("latestStates", latestStates);

