// State-Event -> Andon-Steuerbefehl
// Verarbeitet start/stop je device.key und behaelt parallele aktive Zustaende.
// Jeder Zustand steuert unabhaengig die zugeordnete Lampe.

const cfg = flow.get("andonPilotConfig");

function diag(level, text, extra) {
    return {
        payload: {
            level: level,
            message: text,
            extra: extra || null,
            sourceTopic: msg.topic,
            at: new Date().toISOString()
        }
    };
}

if (!cfg) {
    return [null, diag("error", "Pilot-Konfiguration ist noch nicht initialisiert.")];
}

const evt = msg.payload;

if (!evt || typeof evt !== "object") {
    return [null, diag("error", "Payload ist kein JSON-Objekt.", { payload: evt })];
}

const deviceKey = evt.device && evt.device.key;
const eventKind = evt.event_kind;
const stateCode = evt.state && evt.state.code ? evt.state.code : "__unknown__";

if (!deviceKey) {
    return [null, diag("error", "device.key fehlt im State-Event.", { event_id: evt.event_id })];
}

if (eventKind !== "start" && eventKind !== "stop") {
    return [null, diag("warn", "event_kind muss 'start' oder 'stop' sein.", {
        deviceKey: deviceKey,
        event_kind: eventKind,
        stateCode: stateCode
    })];
}

const mapping = cfg.workplaceMap[deviceKey];
if (!mapping) {
    return [null, diag("warn", "Kein Andon-Mapping fuer device.key vorhanden.", {
        deviceKey: deviceKey,
        stateCode: stateCode,
        eventKind: eventKind
    })];
}

// Mapping gegen die Gateway-Konfiguration validieren.
const circuit = cfg.gatewayConfig.circuits.find(c => c.circuit_id === mapping.circuit_id);
const andonExists = circuit && circuit.andon_lights.some(a => a.andon_id === mapping.andon_id);

if (!andonExists) {
    return [null, diag("error", "Mapping verweist auf eine nicht konfigurierte Andon-Ampel.", {
        deviceKey: deviceKey,
        mapping: mapping
    })];
}

const allActive = flow.get("andonActiveStates") || {};
const deviceActive = allActive[deviceKey] || {};

if (eventKind === "start") {
    deviceActive[stateCode] = {
        startedAt: evt.occurred_at || new Date().toISOString(),
        eventId: evt.event_id || null
    };
} else {
    delete deviceActive[stateCode];
}

allActive[deviceKey] = deviceActive;
flow.set("andonActiveStates", allActive);

// Effektive Regel bestimmen.
// Aktive Zustaende in Lampenzustand umsetzen.
// Jeder Zustand steuert unabhaengig genau eine Lampe.

const activeCodes = Object.keys(deviceActive);

// Grundzustand: alle Lampen aus
const lights = ["off", "off", "off"];

activeCodes.forEach(code => {
    const lampIndex = cfg.stateLampMap[code];

    if (lampIndex !== undefined && lampIndex >= 0 && lampIndex < lights.length) {
        lights[lampIndex] = "steady";
    }
});

const command = {
    circuit_id: mapping.circuit_id,
    andon_id: mapping.andon_id,
    lights: lights,
    interval: cfg.interval
};

// Doppelte identische Retained-Kommandos unterdruecken.
const lastCommands = flow.get("andonLastCommands") || {};
const commandKey = JSON.stringify(command);

if (lastCommands[deviceKey] === commandKey) {
    return [null, diag("info", "Identischer Andon-Zustand bereits publiziert; Nachricht unterdrueckt.", {
        deviceKey: deviceKey,
        activeStates: activeCodes,
        command: command
    })];
}

lastCommands[deviceKey] = commandKey;
flow.set("andonLastCommands", lastCommands);

msg.topic = cfg.commandTopicBase + deviceKey + cfg.commandTopicSuffix;
msg.payload = command;
msg.qos = 1;
msg.retain = true;

return [
    msg,
    diag("info", "Andon-Steuerbefehl erzeugt.", {
        deviceKey: deviceKey,
        activeStates: activeCodes,
        commandTopic: msg.topic,
        command: command
    })
];

